rules_version = '2';
service cloud.firestore {
  match /databases/{database}/documents {
    match /users/{userId} {
      allow read, write: if request.auth.uid == userId;
    }
    match /chats/{chatId} {
      allow read: if request.auth.uid in resource.data.participantIds;
      match /messages/{msgId} {
        allow read: if request.auth.uid in
          get(/databases/$(database)/documents/chats/$(chatId))
            .data.participantIds;
        allow create: if request.auth.uid == request.resource.data.senderId;
      }
    }
    match /appointments/{appId} {
      allow read: if request.auth.uid == resource.data.therapistId
                  || request.auth.uid == resource.data.patientId;
      allow write: if request.auth.uid == resource.data.therapistId;
    }
  }
}

Future<void> sendMessage(String chatId, String text) async {
  final localId = const Uuid().v4();

  // Optimistic insert — visible in UI immediately
  _pending[localId] = Message(
    id: localId,
    senderId: _auth.uid,
    text: text,
    timestamp: DateTime.now(),
    status: Status.sending,
  );
  notifyListeners();

  try {
    // Firestore SDK queues this automatically when offline
    await _db.collection('chats/$chatId/messages').add({
      'senderId': _auth.uid,
      'text': text,
      'timestamp': FieldValue.serverTimestamp(),
    });
    _pending[localId] = _pending[localId]!.copyWith(status: Status.sent);
  } catch (_) {
    _pending[localId] = _pending[localId]!.copyWith(status: Status.failed);
  }
  notifyListeners();
}

Future<bool> hasConflict(
    String therapistId, DateTime start, DateTime end) async {
  final snap = await _db
      .collection('appointments')
      .where('therapistId', isEqualTo: therapistId)
      .where('status', isEqualTo: 'confirmed')
      .get();

  return snap.docs.any((doc) {
    final s = (doc['startTime'] as Timestamp).toDate();
    final e = (doc['endTime'] as Timestamp).toDate();
    // Two intervals overlap when: newStart < existEnd AND newEnd > existStart
    return start.isBefore(e) && end.isAfter(s);
  });
}

// Pure scoring function — no Firebase dependency
double scoreMatch(List<String> required, List<String> candidate) {
  if (required.isEmpty) return 0.0;
  final owned = candidate.map((s) => s.toLowerCase()).toSet();
  final hits  = required.where((s) => owned.contains(s.toLowerCase())).length;
  return (hits / required.length) * 100.0;
}

// Rank all active jobs for a candidate, highest score first
Future<List<JobMatch>> rankForCandidate(String candidateId) async {
  final profile = await _profiles.get(candidateId);
  final jobs    = await _jobs.getAll();
  return jobs
      .map((j) => JobMatch(job: j,
            score: scoreMatch(j.requiredSkills, profile.skills)))
      .where((m) => m.score > 0)
      .toList()
    ..sort((a, b) => b.score.compareTo(a.score));
}

// Firestore limitation: only ONE arrayContains allowed per query.
// Strategy: server narrows on the first skill, client filters the rest.
Future<List<Job>> fetchMatchingJobs(List<String> skills) async {
  final snap = await _db
      .collection('jobs')
      .where('requiredSkills', arrayContains: skills.first)
      .where('isActive', isEqualTo: true)
      .get();

  // Client-side pass: apply remaining skill requirements
  return snap.docs
      .map(Job.fromDoc)
      .where((job) => skills.skip(1).every((skill) =>
          job.requiredSkills
              .map((r) => r.toLowerCase())
              .contains(skill.toLowerCase())))
      .toList();
}

import mediapipe as mp

L = mp.solutions.hands.HandLandmark

def classify_gesture(lm):
    # In image space: smaller Y = higher on screen
    index_up  = lm[L.INDEX_FINGER_TIP].y  < lm[L.INDEX_FINGER_PIP].y
    middle_up = lm[L.MIDDLE_FINGER_TIP].y < lm[L.MIDDLE_FINGER_PIP].y
    ring_up   = lm[L.RING_FINGER_TIP].y   < lm[L.RING_FINGER_PIP].y
    pinky_up  = lm[L.PINKY_TIP].y         < lm[L.PINKY_PIP].y

    if index_up and not middle_up and not ring_up and not pinky_up:
        return 'draw'         # Only index raised
    if index_up and middle_up and not ring_up and not pinky_up:
        return 'erase'        # Index + middle raised
    if not any([index_up, middle_up, ring_up, pinky_up]):
        return 'clear'        # All fingers closed (fist)
    return 'idle'

from collections import deque
import threading, queue, cv2, numpy as np

class Smoother:
    def __init__(self, n=5):
        self.xs, self.ys = deque(maxlen=n), deque(maxlen=n)
    def smooth(self, x, y):
        self.xs.append(x); self.ys.append(y)
        return int(np.mean(self.xs)), int(np.mean(self.ys))

class CameraThread(threading.Thread):
    def __init__(self, src=0):
        super().__init__(daemon=True)
        self.cap = cv2.VideoCapture(src)
        self._q  = queue.Queue(maxsize=2)
    def run(self): 
        while True:
            ok, frame = self.cap.read()
            if ok:
                if self._q.full():          # Drop oldest — stay current
                    try: self._q.get_nowait()
                    except queue.Empty: pass
                self._q.put(frame)
    def read(self): return self._q.get(timeout=1.0)
